  if (fresh.length) await supabase.from("agent_proposals").insert(fresh.map(item => ({ workspace_id: workspace.id, agent: "chat", kind: "recurring_edit", confidence: 100, ...item, payload: recurringEditSchema.parse(item.payload) })));
